import React from 'react';

const About = () => (
  <section id="about" className="py-16 bg-white hover:bg-gray-50 transition-colors duration-300">
    <div className="container mx-auto text-center">
      <h2 className="text-3xl font-bold mb-4 hover:text-gray-700 transition-colors duration-200">About Me</h2>
      <p className="text-lg mx-auto max-w-2xl hover:shadow-md transition-shadow duration-200">
        I am a passionate DevOps Engineer with over 5 years of experience in automating deployments, managing cloud infrastructures, and optimizing CI/CD pipelines. Based in Lahore, Pakistan, I specialize in AWS, Kubernetes, and modern DevOps tools to deliver scalable solutions.
      </p>
    </div>
  </section>
);

export default About;
